#include <bits/stdc++.h>
using namespace std;
int selectK(vector<int>a,int k){if(a.size()<=5){sort(a.begin(),a.end());return a[k];}vector<int>med;for(int i=0;i<(int)a.size();i+=5){vector<int>g(a.begin()+i,a.begin()+min((int)a.size(),i+5));sort(g.begin(),g.end());med.push_back(g[g.size()/2]);}int pivot=selectK(med,med.size()/2);vector<int>lo,eq,hi;for(int x:a)(x<pivot?lo:x>pivot?hi:eq).push_back(x);if(k<(int)lo.size())return selectK(lo,k);if(k<(int)(lo.size()+eq.size()))return pivot;return selectK(hi,k-lo.size()-eq.size());}
int main(){int n;cout<<"Number of values: ";if(!(cin>>n)||n<=0||n>45)return 1;vector<int>a(n);for(int&x:a)cin>>x;int k;cout<<"k (1-based smallest): ";cin>>k;if(k<1||k>n)return 1;cout<<"k-th smallest: "<<selectK(a,k-1)<<"\n";long long target;cout<<"Subset-sum target: ";cin>>target;int mid=n/2;vector<long long>L,R;for(int mask=0;mask<(1<<mid);mask++){long long s=0;for(int i=0;i<mid;i++)if(mask>>i&1)s+=a[i];L.push_back(s);}int rn=n-mid;for(int mask=0;mask<(1<<rn);mask++){long long s=0;for(int i=0;i<rn;i++)if(mask>>i&1)s+=a[mid+i];R.push_back(s);}sort(R.begin(),R.end());bool found=false;for(long long x:L)if(binary_search(R.begin(),R.end(),target-x)){found=true;break;}cout<<"Subset sum exists: "<<(found?"YES":"NO")<<"\n";}
